    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpGlx = GLX()
        tmpGlx.Init(buf, pos)
        return cls.InitFromObj(tmpGlx)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpGlx):
        x = GLXT()
        x._UnPack(tmpGlx)
        return x

    # GLXT
    def _UnPack(self, GLX):
        if GLX is None:
            return
        self.ID = GLX.ID()
        self.NAME = GLX.NAME()
        if not GLX.DESIGNATIONSIsNone():
            self.DESIGNATIONS = []
            for i in range(GLX.DESIGNATIONSLength()):
                self.DESIGNATIONS.append(GLX.DESIGNATIONS(i))
        self.RA_DEG = GLX.RA_DEG()
        self.DEC_DEG = GLX.DEC_DEG()
        self.CSO_ID = GLX.CSO_ID()
        self.DISTANCE_MPC = GLX.DISTANCE_MPC()
